import React, { useEffect, useRef } from "react";
import Header from "../../../Layout/header";
import { useState } from "react";
import TableTitle from "../../Form/TableTitle";
import { apiUrls } from "../../../utils/apiUrls";
import { callAPI } from "../../../utils/apiUtils";
import {
  ApiLoder,
  CustomMessages,
  ErrorMessage,
  HasPermission,
  SuccessMessage,
} from "../../../helpers/common";
import Tab from "../../Form/Tab";
import { GhlSvg, StripeSvg } from "../../../SvgFile/Index";
import InputField from "../../Form/InputField";
import SimpleReactValidator from "simple-react-validator";
import SubmitButton from "../../Form/SubmitButton";
import { Link } from "react-router-dom";
import Stripe from "./Stripe";
import moment from "moment";

export default function Index() {
  const [loder, setLoader] = useState(false);
  const [tabdata, setTabdata] = useState("#pills-overview-tab");
  const [value, setValue] = useState({
    apIkey: "",
    pipelineId: "",
    locationId: "",
    baseAddress: "",
  });
  const simpleValidator = useRef(
    new SimpleReactValidator({ messages: CustomMessages })
  );
  const [, forceUpdate] = useState();
  const TenantlistAPI = async () => {
    setLoader(true);
    try {
      const apiResponse = await callAPI(apiUrls.GetGHLConfiguration, {}, "GET");
      setLoader(false);
      if (apiResponse?.data?.isSuccess) {
        setValue(apiResponse?.data?.data);
      } else {
        setValue({});
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      setLoader(false);
    }
  };
  useEffect(() => {
    TenantlistAPI();
    // eslint-disable-next-line
  }, []);

  const Tablist = [
    HasPermission("GHLView") && {
      status: true,
      id: "#ghl",
      svg: <GhlSvg/>,
      title: "GHL Configuration",
    },
    HasPermission("StripeView") && {
      status: false,
      id: "#Stripe",
      svg: <StripeSvg/>,
      title: "Stripe Configuration",
    },
  ];

  const handleTabchnage = (value) => {
    setTabdata(value || Tablist[0].id);
  };
  const initialActiveTab = localStorage.getItem("activeTab2") || Tablist[0].id;

  const handleChange = (e) => {
    const value = e.target?.value;
    const name = e.target?.name;
    setValue((val) => {
      return { ...val, [name]: value };
    });
  };
  const handleSubmit = async (e) => {
    e.preventDefault();
    const formValid = simpleValidator.current.allValid();
    if (!formValid) {
      simpleValidator.current.showMessages();
      forceUpdate(1);
    } else {
      setLoader(true);
      try {
        const response = await callAPI(
          apiUrls.AddGHLConfiguration,
          {},
          "POST",
          value
        );
        setLoader(false);
        if (response.data.isSuccess) {
          SuccessMessage(response.data?.message);
          TenantlistAPI();
        } else {
          ErrorMessage(response.data.message);
        }
      } catch (error) {
        setLoader(false);
      }
    }
  };


 const handleChnage = async () => {
    const isConfirmed = window.confirm("Are you sure you want to sync Ghl Configuration?");
    if (isConfirmed) {
      setLoader(true);
    try {
      const response = await callAPI(apiUrls.ghlsync, {}, "GET");
      setLoader(false);
      if (response.data.isSuccess) {
        SuccessMessage(response.data.message);
        TenantlistAPI();
       
      } else {
        ErrorMessage(response.data.message);
      }
    } catch (error) {
      setLoader(false);
    }
  }
  else {
    setLoader(false);
  }
  };

  return (
    <>
      {loder && <ApiLoder />}
      <div className="intersight_content">
        <Header title="Configuration" />
        <div className="body_content">
          <div className="contact-profile">
            <div className="engage-tabs">
              <ul className="nav nav-pills" id="pills-tab" role="tablist">
                <Tab Tablist={Tablist} handleTabchnage={handleTabchnage} />
              </ul>
              <div className="tab-content" id="ghl">
                <div
                  className={`tab-pane fade ${
                    initialActiveTab === "#ghl" ? "show active" : ""
                  }`}
                  id="ghl"
                  role="tabpanel"
                  aria-labelledby="pills-overview-tab"
                  tabIndex={0}
                >
                  <div className="contact-profile">
                    <div className="d-flex align-items-center justify-content-between mb-30">
                      <TableTitle title="Manage GHL Configuration" />
                    </div>
                    <div className="form-design">
                      <form onSubmit={handleSubmit}>
                        <div className="seeting_page">
                          <div className="form-group">
                            <InputField
                              labelName={"Api Key"}
                              placeholderName={"Enter Api Key"}
                              type={"text"}
                              handleChange={handleChange}
                              id={"apIkey"}
                              name={"apIkey"}
                              value={value.apIkey}
                              required={true}
                            />
                            <div className="error">
                              {simpleValidator.current.message(
                                "apIkey",
                                value?.apIkey,
                                `required`
                              )}
                            </div>
                          </div>

                          <div className="form-group">
                            <InputField
                              labelName={"Pipe line Info"}
                              placeholderName={"Enter Pipe line Info"}
                              type={"text"}
                              handleChange={handleChange}
                              id={"pipelineId"}
                              name={"pipelineId"}
                              value={value.pipelineId}
                              required={true}
                            />
                            <div className="error">
                              {simpleValidator.current.message(
                                "pipelineInfo",
                                value?.pipelineId,
                                `required`
                              )}
                            </div>
                          </div>

                          <div className="form-group">
                            <InputField
                              labelName={"Location Id"}
                              placeholderName={"Enter LocationId"}
                              type={"text"}
                              handleChange={handleChange}
                              id={"locationId"}
                              name={"locationId"}
                              value={value.locationId}
                              required={true}
                            />
                            <div className="error">
                              {simpleValidator.current.message(
                                "Location Id",
                                value?.locationId,
                                `required`
                              )}
                            </div>
                          </div>

                          <div className="form-group">
                            <InputField
                              labelName={"Base Address"}
                              placeholderName={"Enter Base Address"}
                              type={"text"}
                              handleChange={handleChange}
                              id={"baseAddress"}
                              name={"baseAddress"}
                              value={value.baseAddress}
                              required={true}
                            />
                            <div className="error">
                              {simpleValidator.current.message(
                                "baseAddress",
                                value?.baseAddress,
                                `required`
                              )}
                            </div>
                          </div>
                           <p>Last Sync : <strong>{moment(new Date()).format("YYYY-MM-DD") || ""}</strong></p>
                          <div className="form-style form-group mt-4">
                            {HasPermission("GHLEdit") && (
                              <SubmitButton
                                type="submit"
                                className="btn blue-btn me-3"
                                name={"Submit"}
                                disabled={loder}
                              />
                            )}
                            <button type="button" onClick={handleChnage} className="btn blue-btn me-3">Sync GHL</button>
                            <Link
                              to={"/dashboard"}
                              className="cancel text-decoration-underline"
                            >
                              Cancel
                            </Link>
                          </div>
                        </div>
                      </form>
                    </div>
                  </div>
                </div>
                {/* vendorlisttab */}

                {HasPermission("StripeView") && (
                  <div
                    className={`tab-pane fade ${
                      initialActiveTab === "#Stripe" ? "show active" : ""
                    }`}
                    id="Stripe"
                    role="tabpanel"
                    aria-labelledby="pills-payment-tab"
                    tabIndex={0}
                  >
                    {tabdata === "#Stripe" && <Stripe/>}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
