import React, { useEffect, useRef } from "react";
import { useState } from "react";
import TableTitle from "../../Form/TableTitle";
import { apiUrls } from "../../../utils/apiUrls";
import { callAPI } from "../../../utils/apiUtils";
import {
  ApiLoder,
  CustomMessages,
  ErrorMessage,
  HasPermission,
  SuccessMessage,
} from "../../../helpers/common";

import InputField from "../../Form/InputField";
import SimpleReactValidator from "simple-react-validator";
import SubmitButton from "../../Form/SubmitButton";
import { Link } from "react-router-dom";

export default function Stripe() {
  const [loder, setLoader] = useState(false);
  const [value, setValue] = useState({
    secretKey: "",
    publishableKey: "",
    cancelUrl: "",
    successUrl: "",
  });
  const simpleValidator = useRef(
    new SimpleReactValidator({ messages: CustomMessages })
  );
  const [, forceUpdate] = useState();
  const TenantlistAPI = async () => {
    setLoader(true);
    try {
      const apiResponse = await callAPI(
        apiUrls.GetStripeConfiguration,
        {},
        "GET"
      );
      setLoader(false);
      if (apiResponse?.data?.isSuccess) {
        setValue(apiResponse?.data?.data);
      } else {
        setValue({});
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      setLoader(false);
    }
  };
  useEffect(() => {
    TenantlistAPI();
    // eslint-disable-next-line
  }, []);

  const handleChange = (e) => {
    const value = e.target?.value;
    const name = e.target?.name;
    setValue((val) => {
      return { ...val, [name]: value };
    });
  };
  const handleSubmit = async (e) => {
    e.preventDefault();
    const formValid = simpleValidator.current.allValid();
    if (!formValid) {
      simpleValidator.current.showMessages();
      forceUpdate(1);
    } else {
      setLoader(true);
      try {
        const response = await callAPI(
          apiUrls.AddStripeConfiguration,
          {},
          "POST",
          value
        );
        setLoader(false);
        if (response.data.isSuccess) {
          SuccessMessage(response.data?.message);
          TenantlistAPI();
        } else {
          ErrorMessage(response.data.message);
        }
      } catch (error) {
        setLoader(false);
      }
    }
  };
  return (
    <>
      {loder && <ApiLoder />}
      <div className="contact-profile">
        <div className="d-flex align-items-center justify-content-between mb-30">
          <TableTitle title="Manage Stripe Configuration" />
        </div>
        <div className="form-design">
          <form onSubmit={handleSubmit}>
            <div className="seeting_page">
              <div className="form-group">
                <InputField
                  labelName={"Secret Key"}
                  placeholderName={"Enter Secret Key"}
                  type={"text"}
                  handleChange={handleChange}
                  id={"secretKey"}
                  name={"secretKey"}
                  value={value.secretKey}
                  required={true}
                />
                <div className="error">
                  {simpleValidator.current.message(
                    "secretKey",
                    value?.secretKey,
                    `required`
                  )}
                </div>
              </div>

              <div className="form-group">
                <InputField
                  labelName={"Publishable Key"}
                  placeholderName={"Enter Publishable Key"}
                  type={"text"}
                  handleChange={handleChange}
                  id={"publishableKey"}
                  name={"publishableKey"}
                  value={value.publishableKey}
                  required={true}
                />
                <div className="error">
                  {simpleValidator.current.message(
                    "publishableKey",
                    value?.publishableKey,
                    `required`
                  )}
                </div>
              </div>

              <div className="form-style form-group mt-4">
                {HasPermission("StripeEdit") && (
                  <SubmitButton
                    type="submit"
                    className="btn blue-btn me-3"
                    name={"Submit"}
                    disabled={loder}
                  />
                )}
                <Link
                  to={"/dashboard"}
                  className="cancel text-decoration-underline"
                >
                  Cancel
                </Link>
              </div>
            </div>
          </form>
        </div>
      </div>
    </>
  );
}
